function uniqueSortedNumbers(values) {
  const unique = [];
  const seen = {};

  for (let i = 0; i < values.length; i++) {
    const num = values[i];
    if (Number.isFinite(num) && !seen[num]) {
      unique.push(num);
      seen[num] = true;
    }
  }

  unique.sort((a, b) => a - b);
  return unique;
}
