Here's a script that creates a form and saves user input. I'll give you a couple of options since "script" can mean different things.

## Option 1: Python (stdlib only, web form)

Zero dependencies — uses Python's built-in `http.server`. Saves to CSV.

```python
import csv
import html
import os
from datetime import datetime
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import parse_qs

DATA_FILE = "submissions.csv"
PORT = 8000

PAGE = """<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Text Form</title>
  <style>
    body {{ font-family: system-ui, sans-serif; max-width: 600px; margin: 3rem auto; }}
    textarea {{ width: 100%; min-height: 150px; padding: .5rem; }}
    button {{ margin-top: .75rem; padding: .5rem 1.25rem; }}
    .note {{ color: #080; }}
  </style>
</head>
<body>
  <h1>Submit some text</h1>
  {message}
  <form method="POST" action="/">
    <textarea name="text" required placeholder="Type here..."></textarea>
    <br>
    <button type="submit">Save</button>
  </form>
</body>
</html>
"""


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        self._respond(PAGE.format(message=""))

    def do_POST(self):
        length = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(length).decode("utf-8")
        text = parse_qs(body).get("text", [""])[0].strip()

        if not text:
            self._respond(PAGE.format(
                message='<p style="color:#c00">Please enter some text.</p>'), status=400)
            return

        self._save(text)
        self._respond(PAGE.format(
            message='<p class="note">Saved. Thank you!</p>'))

    def _save(self, text):
        new_file = not os.path.exists(DATA_FILE)
        with open(DATA_FILE, "a", newline="", encoding="utf-8") as f:
            writer = csv.writer(f)
            if new_file:
                writer.writerow(["timestamp", "text"])
            writer.writerow([datetime.now().isoformat(timespec="seconds"), text])

    def _respond(self, content, status=200):
        data = content.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)


if __name__ == "__main__":
    print(f"Serving on http://localhost:{PORT} — Ctrl+C to stop")
    HTTPServer(("", PORT), Handler).serve_forever()
```

Run it with `python3 script.py`, then open http://localhost:8000. Each submission appends a timestamped row to `submissions.csv`.

## Option 2: Browser-only (HTML + JS)

Saves to `localStorage` — no server, no install. Open the file directly in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Text Form</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 600px; margin: 3rem auto; }
    textarea { width: 100%; min-height: 150px; padding: .5rem; box-sizing: border-box; }
    li { margin: .4rem 0; }
  </style>
</head>
<body>
  <h1>Submit some text</h1>
  <form id="f">
    <textarea id="text" required placeholder="Type here..."></textarea><br>
    <button type="submit">Save</button>
  </form>
  <h2>Saved entries</h2>
  <ul id="list"></ul>

  <script>
    const KEY = "savedText";
    const form = document.getElementById("f");
    const field = document.getElementById("text");
    const list = document.getElementById("list");

    const load = () => JSON.parse(localStorage.getItem(KEY) || "[]");

    function render() {
      list.innerHTML = "";
      for (const item of load()) {
        const li = document.createElement("li");
        li.textContent = `${item.date} — ${item.text}`;
        list.appendChild(li);
      }
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const text = field.value.trim();
      if (!text) return;
      const entries = load();
      entries.push({ text, date: new Date().toLocaleString() });
      localStorage.setItem(KEY, JSON.stringify(entries));
      field.value = "";
      render();
    });

    render();
  </script>
</body>
</html>
```

## Which to pick

- **Need data on disk / multiple users?** Python version.
- **Quick demo, single machine?** HTML version.

A few notes on the Python one: input is passed through `html.escape` implicitly by being re-rendered only in the success/error message paths — actually, if you want the submitted text echoed back, wrap it with `html.escape(text)` first. It's also not production-ready: no CSRF protection, no size limits on the request body, and it binds to all interfaces. For real deployment, put it behind a reverse proxy and use a framework like Flask or FastAPI.

For the browser version, note `localStorage` is per-browser and per-origin — data won't follow the user across devices, and it's wiped if they clear browsing data.

# Text Input Form with Save

Below are three versions — pick the one matching your stack.

## Option 1: Python (Flask) — server-side save to file

**`app.py`**

```python
import json
import os
from datetime import datetime

from flask import Flask, redirect, render_template, request, url_for

app = Flask(__name__)
DATA_FILE = "entries.json"


def load_entries():
    if not os.path.exists(DATA_FILE):
        return []
    with open(DATA_FILE, "r", encoding="utf-8") as f:
        try:
            return json.load(f)
        except json.JSONDecodeError:
            return []


def save_entries(entries):
    # Write atomically so a crash mid-write can't corrupt the file
    tmp = DATA_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(entries, f, indent=2, ensure_ascii=False)
    os.replace(tmp, DATA_FILE)


@app.route("/", methods=["GET", "POST"])
def index():
    error = None
    if request.method == "POST":
        text = request.form.get("text", "").strip()
        if not text:
            error = "Text cannot be empty."
        elif len(text) > 5000:
            error = "Text is too long (max 5000 characters)."
        else:
            entries = load_entries()
            entries.append(
                {"text": text, "saved_at": datetime.now().isoformat(timespec="seconds")}
            )
            save_entries(entries)
            return redirect(url_for("index"))

    return render_template("index.html", entries=load_entries(), error=error)


if __name__ == "__main__":
    app.run(debug=True, port=5000)
```

