## Option 2: Browser only — save to `localStorage`

No server needed, but data lives in that one browser and is lost if the user clears site data.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Text Saver</title>
</head>
<body>
  <h1>Save some text</h1>

  <form id="form">
    <textarea id="text" maxlength="5000" required
              style="width:100%;min-height:120px;font:inherit"></textarea>
    <button type="submit">Save</button>
  </form>

  <h2>Saved</h2>
  <ul id="list"></ul>

  <script>
    const KEY = "saved-texts";
    const form = document.getElementById("form");
    const input = document.getElementById("text");
    const list = document.getElementById("list");

    const load = () => JSON.parse(localStorage.getItem(KEY) || "[]");
    const store = (items) => localStorage.setItem(KEY, JSON.stringify(items));

    function render() {
      const items = load();
      list.innerHTML = "";
      // newest first
      [...items].reverse().forEach((item, i) => {
        const li = document.createElement("li");
        li.textContent = item.text + "  ";
        const meta = document.createElement("small");
        meta.style.color = "#666";
        meta.textContent = new Date(item.savedAt).toLocaleString();
        li.appendChild(meta);
        list.appendChild(li);
      });
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const text = input.value.trim();
      if (!text) return;
      const items = load();
      items.push({ text, savedAt: new Date().toISOString() });
      store(items);
      input.value = "";
      render();
    });

    render();
  </script>
</body>
</html>
```

Note: `textContent` is used rather than `innerHTML` so saved text can never inject markup.

