## Option 3: Node (Express) — save to a JSON file

```js
// npm init -y && npm install express
const express = require("express");
const fs = require("fs/promises");
const path = require("path");

const app = express();
const DATA = path.join(__dirname, "entries.json");

app.use(express.urlencoded({ extended: false }));

async function loadEntries() {
  try {
    return JSON.parse(await fs.readFile(DATA, "utf8"));
  } catch {
    return [];
  }
}

app.get("/", async (req, res) => {
  const entries = await loadEntries();
  const rows = entries
    .slice()
    .reverse()
    .map(
      (e) =>
        `<li>${escapeHtml(e.text)}<br><small>${e.savedAt}</small></li>`
    )
    .join("");
  res.send(`<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Text Saver</title></head>
<body style="font-family:system-ui;max-width:640px;margin:3rem auto">
  <h1>Save some text</h1>
  <form method="post" action="/save">
    <textarea name="text" maxlength="5000" required
      style="width:100%;min-height:120px;font:inherit"></textarea><br>
    <button type="submit">Save</button>
  </form>
  <h2>Saved (${entries.length})</h2>
  <ul>${rows || "<li>Nothing yet.</li>"}</ul>
</body></html>`);
});

app.post("/save", async (req, res) => {
  const text = (req.body.text || "").trim();
  if (text && text.length <= 5000) {
    const entries = await loadEntries();
    entries.push({ text, savedAt: new Date().toISOString() });
    await fs.writeFile(DATA, JSON.stringify(entries, null, 2));
  }
  res.redirect("/");
});

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  }[c]));
}

app.listen(3000, () => console.log("http://localhost:3000"));
```

---

**Notes on the server versions**

- Both validate on the server, not just in the browser — the `required` and `maxlength` attributes are convenience, not security.
- `escapeHtml` / Jinja autoescaping matter: without them, a user typing `<script>` gets it executed for everyone viewing the list. Flask's Jinja templates autoescape by default; the Node version needs the explicit call.
- JSON files are fine for a demo or single user. For anything concurrent or multi-user, use SQLite (`sqlite3` / `better-sqlite3`) so writes are transactional.
- Neither version authenticates anyone. If this is going anywhere public, add auth or it's an open message board for spam.
